add('reseller-staff','GET','/api/reseller/customers/{id}','Inspect own customer management detail',resellerStaff,'Current selected active parent and membership required. Support/billing may inspect safe management metadata without business records or credentials. Transferred, detached or other-parent IDs return404. No arbitrary query parameters are accepted.',null,resellerCustomer);
add('reseller-staff','PUT','/api/reseller/customers/{id}','Rename own customer workspace',resellerManagers,'Requires current customer_control_version in version, reason and request_id. Updates only workspace name and advances control version. Customer records, memberships, subdomain, private settings and billing are retained. Stale control version409; inspect current saved detail after an uncertain response.',{...object({...customerCommand,name:{...str('Workspace name',100),minLength:2}},[...Object.keys(customerCommand),'name']),additionalProperties:false},resellerCustomer);
add('reseller-staff','POST','/api/reseller/customers/{id}/state','Suspend or resume own customer access',resellerManagers,'Requires current customer_control_version, reason and request_id. Suspension revokes customer sessions and blocks shared runtime access without deleting records, members or credentials. Resume clears only the reseller customer control; platform suspension, contract policy and billing still apply. Stale version409. Does not cancel or refund a subscription.',{...object({...customerCommand,suspended:bool('Reseller customer access suspension')},[...Object.keys(customerCommand),'suspended']),additionalProperties:false},resellerCustomer);
add('reseller-staff','PUT','/api/reseller/customers/{id}/plan','Assign an exact own retail version','Reseller owner, administrator or billing','Requires current assignment version, exact retail plan/version, reason and request_id. Revalidates current wholesale ceilings/capabilities and trial allowance. Records remain after reduced limits and further growth is blocked. Existing trial and provider billing are untouched; retail prices remain catalog metadata. Wrong parent404; stale version409.',{...object({...customerCommand,retail_plan_id:uuid,retail_plan_version:version},[...Object.keys(customerCommand),'retail_plan_id','retail_plan_version']),additionalProperties:false},resellerCustomer);
add('reseller-staff','POST','/api/reseller/customers/{id}/owner-invitation','Manage customer owner invitation',resellerManagers,'Pending owner only, current invitation version/reason/request_id required. link reveals a valid token only to the current issuer. renew replaces the token and issuer with seven-day expiry; old links fail. revoke permanently invalidates the current link. Accepted/owned customers cannot change invitations. Renewal response interruption requires reading the saved version and an explicit current-issuer link action; stale retries return409. No message is sent. Private token is returned only for link/renew; never log it or put it in query parameters.',{...object({...customerCommand,operation:enumOf('link|renew|revoke')},[...Object.keys(customerCommand),'operation']),additionalProperties:false},object({id:uuid,email,version,expires_at:zonedTime,revoked:bool('Invitation revoked'),invitation_token:{type:['string','null'],description:'Private current bearer token for link/renew only'}}));
