add('reseller-staff','POST','/api/reseller/plans','Publish own retail plan',resellerManagers,'Current owner/admin role and active selected organization required. Cannot choose another parent or platform actor. Definition limits/features/trial must stay within the current wholesale grant; prices use supported currency minor units. Explicit request_id and reason required. Same actor/request/input retries return200 with the same immutable receipt; changed input conflicts. Records actual reseller staff authorship and audit. Does not collect payment or reassign existing customers.',{...object({...retailPublication,key:resellerKey},[...Object.keys(retailPublication),'key']),additionalProperties:false},retailPublicationReceipt,201);
