add('reseller-staff','GET','/api/reseller/members','Read own organization team',resellerManagers,'Current owner/admin membership and active contract required. Safe own staff identity/membership/MFA readiness only, 25 per UUID cursor. No hashes, factors, recovery codes or other organization memberships.',null,object({items:array(resellerMember,0,25),next_cursor:nullableId},['items','next_cursor']),200,{cursor:uuid});
add('reseller-staff','GET','/api/reseller/members/{id}','Read own team member',resellerManagers,'Current owner/admin membership, selected parent and active contract required. Exact member detail independent of list pagination. Wrong parent or missing member returns404. No credentials or other organization memberships.',null,resellerMember);
add('reseller-staff','GET','/api/reseller/members/creations/{requestId}','Recover own saved team membership',resellerManagers,'Only the original currently authorized owner/admin in the selected active organization can recover a membership creation after timeout or reload. Other actors, parents and missing receipts return404. This read creates no membership and returns no initial password.',null,resellerMember);
add('reseller-staff','POST','/api/reseller/members','Add organization team member',resellerManagers,'Current active owner/admin role required and revalidated at commit. Admin cannot create owners. Explicit new/existing account mode; same actor/request_id/input retry returns200 saved result. Initial passwords are never returned or emailed. The new person enrolls their own MFA.',resellerMemberCreate,resellerMember,201);
add('reseller-staff','PUT','/api/reseller/members/{id}','Change own team role or access',resellerManagers,'Version and reason required. Admin cannot manage/promote owners; owner may manage owners except removing the last enabled owner. Changed roles/access revoke all reseller sessions/challenges for the target account across organizations; customer memberships and records remain.',resellerMemberUpdate,resellerMember);
