add('reseller-api','GET','/api/v1/reseller/customers','List linked reseller customers',resellerScoped,'Requires reseller.customers.read. Returns only the key organization’s linked workspace id/name/slug, assignment version, retail plan/version and updated_at. No users, memberships, CRM, financial records, messages or provider credentials. 25 rows per cursor page; transferred/detached customers disappear on the next request.',null,platformDirectory,200,{cursor:uuid});
add('reseller-api','GET','/api/v1/reseller/plans','List reseller retail plans',resellerScoped,'Requires reseller.plans.read. Returns this organization’s current retail catalog version, currency/minor-unit prices, limits and capabilities. Prices are metadata, not a provider charge. 25 rows per cursor page. No cross-reseller ID lookup or mutation.',null,platformDirectory,200,{cursor:uuid});
add('reseller-api','GET','/api/v1/reseller/usage','Read reseller usage allowance',resellerScoped,'Requires reseller.usage.read. Eight aggregate live-resource gauges, customer count, current wholesale version/limits/capabilities and collection_configured=false. No consumed credits, private customer content or settlement ledger is exposed.',null,{type:'object',description:'reseller_id, usage(users/contacts/custom_records/pipelines/workflows/active_workflows/integrations/calendars), customer_count, grant_version, limits, aggregate_limits, max_workspaces, features and collection_configured=false.'});
