add('platform','PUT','/api/sa/resellers/{id}','Approve or update reseller lifecycle policy',platformAdmin,'Requires the current organization version and reason. Serializes against customer transfers and guarded resource growth. Approval, suspension, policy and contract edits preserve customer data. retain_access preserves customer operation; suspend_access also suspends linked customer access while status/contract is not active. Emits attributed reseller organization lifecycle events through the existing shared outbox. Contract mode is metadata; no automatic provider charge.',{...resellerUpdate,additionalProperties:false},resellerDetail);
add('platform','GET','/api/sa/resellers/{id}/grants','Read immutable wholesale grant history',commercialRead,'Returns25 immutable grant versions newest first, current_version and next_before. before selects older history. Existing retail versions remain pinned; current wholesale reductions clamp effective workspace allowances without removing existing resources.',null,{type:'object'},200,{before:version});
add('platform','POST','/api/sa/resellers/{id}/grants','Publish a wholesale grant',commercialAccess,'Requires current grant version and reason. Publishes an immutable validated reduction of the selected platform plan, updating the reseller current grant pointer. Resource growth is serialized against publication; shared hard ceilings and maximum customer count apply to subsequent growth. Existing records are retained. Emits reseller.customer.plan_changed for linked customers with reseller/tenant/schema metadata.',{...object({version,definition:ref('ResellerGrantDefinition'),reason:platformReason},['version','definition','reason']),additionalProperties:false},resellerDetail,201);
add('platform','GET','/api/sa/resellers/{id}/plans','List reseller retail packages',commercialRead,'Returns25 current retail plan headers with name/currency/monthly/annual/setup catalog prices and trial days, ordered by UUID. These prices do not change DryKraft provider subscriptions or customer billing records.',null,platformDirectory,200,{cursor:uuid});
add('platform','GET','/api/sa/resellers/{id}/plans/{planId}','Read retail package versions',commercialRead,'Returns the reseller-owned plan header,25 immutable versions newest first and next_before. Each version records its publication wholesale grant. Customer assignment stays pinned when a new version is published.',null,{type:'object'},200,{before:version});
add('platform','POST','/api/sa/resellers/{id}/plans','Create a bounded retail package',commercialAccess,'Approved reseller with current contract required. Creates immutable retail version1 with audit. Eight limits and six capabilities may only reduce current wholesale allowances; trial_days may not exceed trial_days_max. Supported currency and monthly/annual/setup minor-unit catalog prices are required. No provider product, payment or invoice is created.',{...object({key:resellerKey,definition:ref('ResellerRetailDefinition'),reason:platformReason},['key','definition','reason']),additionalProperties:false},{type:'object'},201);
add('platform','POST','/api/sa/resellers/{id}/plans/{planId}/versions','Publish another retail package version',commercialAccess,'Requires the current retail version, approved reseller/current contract and reason. Concurrent publication conflicts instead of overwriting. Immutable earlier prices remain pinned to customer assignments. Limits/features/trial are validated against the current wholesale grant; no automatic customer reassignment or provider charge occurs.',{...object({version,definition:ref('ResellerRetailDefinition'),reason:platformReason},['version','definition','reason']),additionalProperties:false},{type:'object'},201);
add('platform','GET','/api/sa/resellers/{id}/customers','List linked customer workspaces',commercialRead,'Returns25 linked workspace IDs/names/slugs, assignment versions and pinned retail version metadata ordered by workspace UUID. No customer business records, user secrets or support access are returned.',null,platformDirectory,200,{cursor:uuid});
add('platform','GET','/api/sa/workspaces/{id}/reseller','Read workspace commercial parent',commercialRead,'Returns current reseller/retail assignment metadata and version0 for never-assigned direct workspaces. Detaching retains its advanced version to prevent stale transfer replay. Organization ownership gives no workspace membership or CRM access.',null,resellerAssignment);
add('platform','PUT','/api/sa/workspaces/{id}/reseller','Assign or transfer a customer commercial parent',platformAdmin,'Requires current assignment version and reason. Select a reseller plus its exact retail version, or clear all three for direct management. Parent locks are sorted before the workspace lock; current contract, plan ownership, wholesale ceilings, customer count and aggregate resource capacity are checked atomically. Transfers preserve records/memberships/provider billing. Emits attributed reseller.customer.transferred or reseller.customer.plan_changed. This endpoint does not perform owner provisioning, snapshot application or approval-based support access.',{...object({version:num('Current assignment version;0 only when never assigned',0),reseller_id:nullableId,retail_plan_id:nullableId,retail_plan_version:{type:['integer','null'],minimum:1},reason:platformReason},['version','reseller_id','retail_plan_id','retail_plan_version','reason']),additionalProperties:false},resellerAssignment);
