add('platform','POST','/api/sa/plans','Create a plan',commercialAccess,'Creates version1 with a required reason and immutable audit. All eight supported live gauges and six capabilities are required. Unimplemented consumed meters are rejected. Workspace price metadata stays USD1/user/month or USD12/user/year; enterprise has no fabricated price or payment state.',{...object({key:{type:'string',pattern:'^[a-z][a-z0-9-]{2,49}$'},definition:ref('PlatformPlanDefinition'),reason:platformReason},['key','definition','reason']),additionalProperties:false},{type:'object'},201);
add('platform','POST','/api/sa/plans/{id}/versions','Publish another plan version',commercialAccess,'Requires the current header version and reason. Concurrent publication yields one new version and a409 for the stale publisher. Earlier definitions cannot be edited/deleted; workspace assignments are not automatically advanced. This does not update a Dodo product or subscription.',{...object({version,definition:ref('PlatformPlanDefinition'),reason:platformReason},['version','definition','reason']),additionalProperties:false},{type:'object'},201);
add('platform','GET','/api/sa/workspaces/{id}/entitlements','Read effective workspace entitlements',commercialRead,'Returns pinned definition, reducing overrides, agreement/trial metadata and live-resource counts only. Contacts count unmerged People; custom_records count records outside the seven built-in objects. Integrations count saved workflow credentials plus enabled outreach/calendar connections/customer webhooks. Calendars count enabled calendars; users count memberships.',null,ref('WorkspaceEntitlements'));
add('platform','PUT','/api/sa/workspaces/{id}/entitlements','Assign a plan or enterprise agreement',commercialAccess,'Requires current entitlement version and reason. Locks against resource growth and trial/plan edits. Overrides can only reduce plan ceilings/capabilities; a null override cannot remove a finite ceiling. Existing resources remain after a lower ceiling; further growth is blocked. Only enterprise versions accept bounded agreements. Current agreement dates and seats can grant write access, without fabricating provider subscription/payment state. Emits billing.entitlements.updated.',{...object({version,plan_id:uuid,plan_version:version,overrides:reductions,agreement:{oneOf:[agreement,{type:'null'}]},reason:platformReason},['version','plan_id','plan_version','overrides','agreement','reason']),additionalProperties:false},ref('WorkspaceEntitlements'));
