add('platform','POST','/api/sa/login','Start platform sign-in',publicAccess,'Central app host only. Separate account password verification returns a five-minute challenge, never a session. Mandatory authenticator enrollment is requested for new accounts. Shared rate protection counts failed attempts.',{...object({email,password:{...str('Current platform password',128),minLength:1}},['email','password']),additionalProperties:false},object({challenge:platformToken,mfa_required:bool('Verification required'),enrollment_required:bool('Enrollment required'),expires_in:{const:300}}));
add('platform','POST','/api/sa/mfa/setup','Read pending platform authenticator setup',publicAccess,'Requires an unexpired password-verified platform challenge for an account without MFA. Returns the private setup key and QR once per saved challenge state; repeated calls reuse that state. Never share or log this response.',{...object({challenge:platformToken},['challenge']),additionalProperties:false},object({secret:str('Private base32 setup key'),qr:str('Private data:image/png QR'),expires_at:str('Challenge expiry')}));
add('platform','POST','/api/sa/mfa','Complete platform sign-in',publicAccess,'Consumes the challenge and a fresh six-digit authenticator or unused recovery code. Enrollment returns ten private one-use recovery codes. Sets drykraft_sa_session: host-only, Secure in production, HttpOnly, SameSite=Strict, path=/api/sa, four-hour maximum and15-minute idle expiry. Up to10 attempts per challenge.',{...object({challenge:platformToken,code:{...str('Authenticator or recovery code',40),minLength:1}},['challenge','code']),additionalProperties:false},object({ok:{const:true},recovery_codes:array(str('Private one-use code'),10,10)}));
