add('automation','GET','/api/automation/workflows/{id}/webhook','Read workflow hook URL',admin,'URL is a secret capability; null before creation. Never expose in public docs/logs.',null,object({url:{type:['string','null'],format:'uri'}}));
add('automation','POST','/api/automation/workflows/{id}/webhook','Create or rotate hook URL',admin,'Old token immediately stops working. Publish an active webhook trigger before receiving runs.',null,object({url:{type:'string',format:'uri'}}));
add('automation','POST','/api/automation/workflows/{id}/run','Run published version',write,'Returns an accepted execution; inspect history for outcome. Published version required. Worker enforces billing access. Sub-workflow trigger inputs must match the closed typed contract before creating a run. Error triggers cannot be started through this endpoint; test their source workflow.',object({input:{...values,default:{}}}),ref('Execution'),202);
add('automation','GET','/api/automation/executions','List recent executions',read,'Latest 100, with workflow_name.',null,array(ref('Execution')));
add('automation','GET','/api/automation/executions/{id}','Inspect execution',read,'Includes workflow name, saved version number, managed Outreach flag and latest 50 incoming/outgoing recovery receipts. One current state row per visited node and iteration_path, ordered by first start; retries update that row rather than storing every attempt. Node names/kinds use the immutable version. A child runtime.call links parent_id, node_id, iteration_path, root_id and ancestry. Server-owned runtime.error_workflow links the one automatically queued handler execution_id/version_id or a skipped reason; runtime.error_handler.source_id links its failed source and is inherited by handler sub-workflows to suppress recursive dispatch. Call node outputs link execution_id/version_id and returned output; caller waits durably, checks terminal child state about every2seconds and reuses the child binding on retry.',null,{allOf:[ref('Execution')],properties:{current_iteration_path:str('Canonical JSON array of [Loop or Split step ID, zero-based item/branch index] pairs; empty outside scoped paths',1024),workflow_name:str('Current workflow name'),version:num('Saved published version number'),managed:bool('Recovery must use Outreach controls'),recoveries:array({type:'object',description:'id, source_id, target_id, mode (rerun/replay/retry), node_id, iteration_path, actor_id, actor_name, created_at'},0,50),nodes:array({type:'object',properties:{node_id:str('Stable published step ID'),node_label:str('Step name from the immutable published version'),iteration_path:str('Saved canonical item/branch scope path; empty outside Loops/Splits',1024),iteration_label:str('Readable Loop/item and Split/branch names from the immutable version')}})}});
add('automation','POST','/api/automation/executions/{id}/cancel','Cancel unfinished execution',write,'Queued/running/waiting/retrying only. Cancels pending descendants by server-owned ancestry. Cannot recall an external side effect already accepted.',null,ref('Execution'));
add('automation','POST','/api/automation/executions/{id}/retry','Retry failed execution',write,'Compatibility action: failed general workflows only, same execution/context/version and completed outputs. Clears terminal timing and records a retry receipt. Managed Outreach recovery is rejected. Prefer recover with a stable request UUID for ambiguous-response safety.',null,ref('Execution'));
add('automation','POST','/api/automation/executions/{id}/recover','Replay a failed step or rerun a saved version',write,'Supply a stable UUID id. Identical retries return the same target execution without another dispatch; changed source/mode/node/iteration conflicts. Retry continues a failed execution from its saved position without node_id; completed outputs are reused. Replay requires node_id and, inside a Loop or Split branch, its exact iteration_path to identify the current failed step/item of a failed execution; keeps completed outputs, context, version, input and HTTP idempotency key. Rerun requires a terminal execution and no node_id; creates a new execution at the original version trigger with original input, even after newer publication or pause. Child full reruns are rejected; start a new family from the parent. Child retry/replay reuses its existing binding; after child recovery, continue the failed parent. All selected-path side effects can repeat. Check uncertain provider outcomes first. Managed Outreach is rejected. Current write role and billing remain required even on receipt replay.',object({id:uuid,mode:enumOf('rerun|replay|retry','Recovery type; retry continues from the saved position'),node_id:str('Required for replay; prohibited for rerun/retry',100),iteration_path:str('Only replay: exact saved canonical JSON item path from execution details; omit/empty for a step outside Loops/Splits',1024)},['id','mode']),ref('Execution'),202);
