add('developer-access','POST','/api/developer/accounts','Create service account',admin,'Current password approval required, limited to 30 approval attempts per account per 15 minutes. Up to 100 active identities. Reuse the same UUID/settings to recover creation without another identity; a completed retry returns 200.',devAccountInput,ref('ServiceAccount'),201);
