add('developer-access','POST','/api/developer/accounts/{id}/keys','Issue a scoped key',admin,'Current password/account version required. Permissions cannot exceed the saved account ceiling. Up to 10 active keys per identity, expiry 1-365 days. Secret appears only in the first 201 response; repeated UUID/settings return 200 and secret=null. This is not a retrievable credential.',object({id:uuid,name:str('Name',100),permissions:ref('DeveloperPermissions'),days:num('Days to expiry',1,365),account_version:version,password},['id','name','permissions','days','account_version','password']),ref('KeyReceipt'),201);
add('developer-access','POST','/api/developer/accounts/{id}/keys/{keyId}/rotate','Rotate a key',admin,'Atomically issue a successor with the old key’s current capped permissions and revoke the old key. In-flight work can finish; old-key future requests fail. Requires current password, key/account versions and a new UUID. Same completed rotation returns 200/secret=null; another rotation of a revoked key conflicts.',object({id:uuid,version,account_version:version,days:num('Days to expiry',1,365),password},['id','version','account_version','days','password']),ref('KeyReceipt'),201);
