add('customer-webhooks','GET','/api/developer/webhooks/{id}/deliveries/{deliveryId}','Inspect delivered envelope and attempts',admin,'Immutable exact envelope plus latest 50 append-only completed attempt rows, newest first. Each row records attempt, secret_version, HTTP status/sanitized error and start/completion time. A process loss after acceptance can leave no completed attempt; receiver must deduplicate the delivery ID.',null,extend('WebhookDelivery',{payload:ref('WebhookEnvelope'),attempt_history:array(object({id:uuid,attempt:num('Lifetime attempt number'),secret_version:version,status:{type:['integer','null']},error:{type:['string','null']},started_at:str('Timestamp'),completed_at:str('Timestamp')}))}));
add('customer-webhooks','POST','/api/developer/webhooks/{id}/deliveries/{deliveryId}/replay','Replay failed delivery',admin,'Current failed-delivery version and acknowledge_duplicate=true required. Restore/reapprove the original destination/event and enable endpoint first. Active billing required. Stable operation UUID resets the retry cycle once; exact retries recover the recorded result. Original body, event ID and delivery ID remain; new timestamp/signature and current secret are used. Delivery is at-least-once and can repeat external effects.',object({id:uuid,version,acknowledge_duplicate:{const:true}},['id','version','acknowledge_duplicate']),ref('WebhookDelivery'));
