add('calendar-connections','PUT','/api/calendar/connections/{id}','Configure calendar sync',write,'Current connection version and editable provider calendar required. Import and export require deliberate selection; OAuth creates disabled connections. Choosing a different calendar is blocked once exports exist. Save clears sync freshness; sync must verify busy ranges before booking.',object({version,calendar_id:str('Provider calendar ID',2000),enabled:bool('Import busy times'),export_enabled:bool('Export DryKraft appointment titles/times/locations; no attendees or internal notes')},['version','calendar_id','enabled','export_enabled']),ref('CalendarConnection'));
