export const apiGroups=[['reseller-staff','Reseller staff accounts'],['reseller-api','Reseller API'],['platform','Platform administration'],['authentication','Authentication & sessions'],['records','Objects & CRM records'],['imports-lists','Imports & smart lists'],['sales-dashboards','Sales & dashboards'],['workspace','Workspace settings'],['team','Team & invitations'],['security','Account security'],['developer-access','Developer access'],['customer-webhooks','Customer webhooks'],['versioned-crm','Versioned CRM API'],['finance','Finance'],['templates','Editable templates'],['billing','Subscription billing'],['calendar','Calendar & appointments'],['calendar-connections','Calendar connections'],['calendar-booking','Public booking'],['automation','Automation'],['outreach-connections','Outreach connections'],['outreach-campaigns','Campaigns & sequences'],['webhooks','Webhooks & callbacks']];

export function openApiDocument(){
  const paths={};
  for(const op of operations){
    const parameters=[...op.path.matchAll(/\{([^}]+)\}/g)].map(([,name])=>({name,in:'path',required:true,schema:['id','record','keyId','deliveryId','requestId','memberId'].includes(name)?uuid:{type:'string'}}));
    for(const [name,schema] of Object.entries(op.query))parameters.push({name,in:'query',required:op.queryRequired.includes(name),schema});
    for(const p of parameters)if(p.name==='resource')p.schema=enumOf('contacts|companies|leads|opportunities|tasks','Built-in collection alias');
    if(op.path.startsWith('/api/settings/organization/'))for(const p of parameters){if(p.name==='kind')p.schema=enumOf('teams|locations','Organization directory kind');if(p.name==='userId')p.schema=uuid;}
    if(op.path.startsWith('/api/v1/')&&['POST','PATCH','DELETE'].includes(op.method))parameters.push({name:'Idempotency-Key',in:'header',required:true,schema:uuid});
    if(op.path==='/api/hooks/{token}')parameters.push({name:'Idempotency-Key',in:'header',required:false,schema:{type:'string',maxLength:200}});
    if(op.path==='/api/billing/dodo/webhook')for(const name of ['webhook-id','webhook-timestamp','webhook-signature'])parameters.push({name,in:'header',required:true,schema:{type:'string'}});
    if((op.path.startsWith('/api/sa/')||op.path.startsWith('/api/reseller/'))&&['POST','PUT','PATCH','DELETE'].includes(op.method))parameters.push({name:'Origin',in:'header',required:true,schema:{type:'string',const:'https://app.drykraft.com'},description:'Required in production; central application host only.'});
    if(op.method==='POST'&&op.path==='/api/outreach/whatsapp/{id}')parameters.push({name:'X-Hub-Signature-256',in:'header',required:true,schema:{type:'string'}});
    const cookie=op.path.startsWith('/api/reseller/')&&op.access!==publicAccess?[{resellerSession:[]}]:op.path.startsWith('/api/sa/')&&op.access!==publicAccess?[{platformSession:[]}]:op.access===resellerScoped?[{resellerKey:[]}]:op.access===scoped?[{bearerKey:[]}]:[publicAccess,'Dodo signature','Meta signature','Meta verify token','Secret hook token','Secret unsubscribe token'].includes(op.access)?[]:[{sessionCookie:[]}];
    const contentType=op.path.endsWith('/ics')?'text/calendar':op.path.endsWith('/pdf')?'application/pdf':op.path.includes('/unsubscribe/')?'text/html':op.method==='GET'&&op.path.endsWith('/whatsapp/{id}')?'text/plain':'application/json';
    const success={description:op.title,...(op.status===302?{headers:{Location:{schema:{type:'string',format:'uri'}}}}:{content:{[contentType]:{schema:op.response}}})};
    if(op.path.startsWith('/api/v1/')&&['POST','PATCH','DELETE'].includes(op.method))success.headers={'Idempotency-Replayed':{schema:{type:'string',enum:['true','false']},description:'True for replay of a completed identical mutation; false for a newly committed mutation.'}};
    const errors=Object.fromEntries([400,401,402,403,404,409,410,413,429,500,502,503].map(code=>[code,{description:({400:'Invalid input',401:'Sign-in or signature required',402:'Active plan required',403:'Access denied',404:'Unavailable resource',409:'Conflict; refresh before retrying',410:'Expired invitation',413:'Body exceeds 512 KB',429:'Rate limited',500:'Unexpected failure',502:'Provider failure',503:'Service unavailable'})[code],content:{'application/json':{schema:ref('Error')}}}]));
    const retryResponse=op.path==='/api/sa/workspaces'||op.path.endsWith('/owner-invitation/email')||(op.method==='POST'&&op.path.endsWith('/api-keys'))||(op.method==='POST'&&op.path.endsWith('/members'))||(op.group==='reseller-staff'&&op.method==='POST'&&op.status===201)?{200:{...success,description:'Identical saved operation replay for the same actor.'}}:['developer-access','customer-webhooks'].includes(op.group)&&op.status===201?{200:{...success,description:'Completed retry; no new identity/key/webhook secret. One-time secret is null on retry.'}}:{};
    paths[op.path]??={};paths[op.path][op.method.toLowerCase()]={operationId:op.id,tags:[apiGroups.find(g=>g[0]===op.group)[1]],summary:op.title,description:op.description+' Access: '+op.access+'.',security:cookie,parameters,...(op.body?{requestBody:{required:true,content:{'application/json':{schema:op.body}}}}:{}),responses:{[op.status]:success,...retryResponse,...errors}};
  }
  return {openapi:'3.1.0',info:{title:'DryKraft current API',version:'2026-10-04',description:'Browser session API plus scoped Bearer service accounts under /api/v1. JSON 512 KB; general API 300/minute per IP, IPv6 /56. Shared Redis counters span API replicas and API restarts: auth/hooks 30/15min; raw Dodo and Meta ingress each 120/minute; Calendar 120/minute plus guest mutations 15/15min. Versioned API also limits 120/minute per key, access approval 30/15min per administrator, password changes 10/15min per account. Fixed windows count unsuccessful attempts. 429 includes Retry-After; unavailable request protection fails closed with 503/Retry-After: 5. API restarts preserve counts, Redis data loss does not. Response shapes with open metadata are described rather than guaranteed as a stable external integration contract.'},servers:[{url:'https://app.drykraft.com'}],tags:apiGroups.map(([,name])=>({name})),paths,components:{securitySchemes:{resellerSession:{type:'apiKey',in:'cookie',name:'drykraft_reseller_session',description:'Separate reseller staff MFA session, host-only HttpOnly Secure SameSite=Strict, path=/api/reseller. Four-hour maximum and15-minute idle expiry. Enabled organization membership/current contract required for management. No customer or platform identity.'},resellerKey:{type:'http',scheme:'bearer',bearerFormat:'dk_res_ opaque reseller key',description:'Dedicated reseller key limited to selected metadata reads under /api/v1/reseller on the central app host. No customer CRM or platform identity. Active contract, expiry, revocation and 120 requests/minute per key apply.'},platformSession:{type:'apiKey',in:'cookie',name:'drykraft_sa_session',description:'Separate platform account MFA session. Central app host only, host-only HttpOnly Secure SameSite=Strict cookie, path=/api/sa. Four-hour maximum and15-minute idle expiry. Workspace cookies/service keys are not accepted.'},bearerKey:{type:'http',scheme:'bearer',bearerFormat:'Opaque DryKraft API key',description:'One-workspace service-account key; accepted only under /api/v1. Explicit per-object/action grants, expiry and revocation apply.'},sessionCookie:{type:'apiKey',in:'cookie',name:'drykraft_session',description:'HTTP-only session cookie created by signup/login, secure in production, same-site lax, seven-day lifetime.'}},schemas:apiSchemas}};
}
